function assertRemoteWriteAllowed(candidate) {
  const maintenanceExpiresAt = Number(process.env.FORGELINK_LOCAL_SECURITY_MAINTENANCE_EXPIRES_AT);
  const maintenanceActive = process.env.FORGELINK_LOCAL_SECURITY_MAINTENANCE === "1" && Number.isFinite(maintenanceExpiresAt) && maintenanceExpiresAt > Date.now();
  if (maintenanceActive) return;
  if (!isRemoteProtectedPath(candidate)) return;
  const error = new Error("SECURITY_PROTECTED_PATH: ForgeLink security, policy, audit, and enforcement files are remote read-only. Enable a current local security-maintenance window to modify them.");
  error.code = "SECURITY_PROTECTED_PATH";
  throw error;
}
